from pathlib import Path
import runpy,json,random,shutil,hashlib
D=runpy.run_path(str(Path(__file__).with_name('batch3-data.py')));ROOT=D['ROOT'];passage=D['passage'];save=D['save'];commentary=D['commentary'];B=D['B']
lessons=[]
def source(ref):return dict(label=('Sahih al-Bukhari ' if ref.startswith('bukhari') else 'Sahih Muslim ')+ref.split(':')[1],url='https://sunnah.com/'+ref,kind='Hadith report')
def lesson(id,title,area,arabic,meaning,transliteration,refs,question,answer,distractors,note=''):
 options=[answer]+distractors;random.Random(id).shuffle(options)
 lessons.append(dict(id=id,title=title,area=area,arabic=arabic,meaning=meaning,transliteration=transliteration,sources=[source(r) for r in refs],question=question,options=options,answer=options.index(answer),note=note,passage=None,audio=False,commentaryUrl=''))
lesson('opening-takbir','Opening takbir','Opening','اللَّهُ أَكْبَرُ','Allah is greater.','Allahu akbar',['bukhari:757','muslim:601'],'What does this phrase proclaim?','Allah’s greatness',['A request for rain','A greeting to people','A mention of a journey'],'Bukhari 757 describes beginning with takbir. Muslim 601 includes these Arabic words within a longer opening expression. The displayed English is our concise rendering.')
questions=[('In whose name does the ayah begin?','Allah',['The angels','The reciter','A prophet']),('Who receives praise in this ayah?','Allah, Lord of the Worlds',['The reciter alone','A ruler','The stars']),('Which descriptions appear in this ayah?','The Beneficent, the Merciful',['The sun and moon','The garden and river','The mountains and valleys']),('Which day is named?','The Day of Judgment',['A market day','The day of migration','The day of harvest']),('To whom are worship and the request for help directed?','Allah alone',['A worldly ruler','The mountains','The reciter']),('What is requested?','Guidance to the straight path',['More possessions','A garden','A journey']),('Whose path is requested?','Those whom Allah has favoured',['Those who go astray','Those who earn anger','A path defined by wealth'])]
for i,(question,answer,distractors) in enumerate(questions,1):
 p=passage(f'1:{i}');options=[answer]+distractors;random.Random(i).shuffle(options)
 lessons.append(dict(id=f'fatiha-{i}',title=f'Al-Fatiha · ayah {i}',area='Al-Fatiha',arabic=p['arabic'],meaning=p['translation'],transliteration='',sources=[],question=question,options=options,answer=options.index(answer),note='Quran text and Pickthall translation. Verse numbering follows the fetched Hafs edition. The audio plays the whole surah, not just this ayah.',passage=p,audio=True,commentaryUrl=commentary(f'1:{i}')))
lesson('bowing','Bowing · glorification','Bowing','سُبْحَانَ رَبِّيَ الْعَظِيمِ','Glory be to my Lord, the Magnificent.','Subhana rabbiya al-azim',['muslim:772'],'How is the Lord described in this phrase?','The Magnificent',['The traveller','The gardener','The witness to a trade'])
lesson('rising','Rising from bowing','Standing','سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ','Allah hears the one who praises Him.','Sami Allahu liman hamidah',['muslim:772'],'Whose praise is mentioned?','The one who praises Allah',['The one counting possessions','The one planting a tree','The one entering a market'])
lesson('standing-praise','Praise while standing','Standing','رَبَّنَا لَكَ الْحَمْدُ','Our Lord, praise belongs to You.','Rabbana laka al-hamd',['muslim:772'],'What is directed to the Lord?','Praise',['A trade offer','A travel instruction','A greeting to a neighbour'])
lesson('prostration','Prostration · glorification','Prostration','سُبْحَانَ رَبِّيَ الأَعْلَى','Glory be to my Lord, the Most High.','Subhana rabbiya al-ala',['muslim:772'],'Which description appears here?','The Most High',['The morning','The garden','The river'])
lesson('tashahhud','Tashahhud · testimony','Sitting','التَّحِيَّاتُ لِلَّهِ، وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلاَمُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ','Greetings, prayers, and good things belong to Allah. Peace, Allah’s mercy, and His blessings be upon you, Prophet. Peace be upon us and Allah’s righteous servants. I testify that none is worthy of worship except Allah, and that Muhammad is His servant and messenger.','At-tahiyyatu lillahi, was-salawatu wat-tayyibat…',['bukhari:831'],'How is Muhammad described at the end of this wording?','Allah’s servant and messenger',['The owner of every kingdom','The author of the Quran','A heavenly body'],'This lesson follows the wording in the cited Ibn Masud report. The short Roman guide covers the opening only. Other authentic tashahhud wordings are also narrated, including Muslim 403a.')
lesson('blessings','Sending blessings','Sitting','اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ، وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ، وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ','O Allah, bestow prayers upon Muhammad and his family as You bestowed prayers upon Ibrahim and his family. You are Praiseworthy, Glorious. O Allah, bless Muhammad and his family as You blessed Ibrahim and his family. You are Praiseworthy, Glorious.','Allahumma salli ala Muhammadin wa ala ali Muhammad…',['bukhari:3370'],'Which earlier prophet is named?','Ibrahim',['Yunus','Musa','Dawud'],'The Roman guide covers the opening only. Read the full Arabic wording and its source; other narrated forms also exist.')
lesson('closing-salam','The closing greeting','Closing','السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ','Peace and Allah’s mercy be upon you.','As-salamu alaykum wa rahmatullah',[],'What does this greeting wish for its recipients?','Peace and Allah’s mercy',['Wealth and status','A safe harvest only','A journey to a mountain'])
lessons[-1]['sources']=[dict(label='Sahih Muslim 431 · Arabic institutional edition',url='https://sunna.alifta.gov.sa/BookToc/ViewMatnPage?bookId=2&mainId=12714',kind='Hadith report',note='Arabic text hosted by the Saudi General Presidency of Scholarly Research and Ifta.')]
audio=dict(title='Al-Fatiha · full surah',creator='Adeel Shaikh',file='/audio/fatiha.mp3',source='https://commons.wikimedia.org/wiki/File:Surah-Fathia.flac',license='CC BY-SA 4.0',licenseUrl='https://creativecommons.org/licenses/by-sa/4.0/',note='Wikimedia MP3 transcode of the creator’s own recording. Audio content unchanged; bundled locally. No endorsement or tajwid certification is implied.')
save('understand-salah-lab',dict(lessons=lessons,audio=audio,methodology='Fifteen lessons cover seven Al-Fatiha ayahs and selected hadith-based recitations from opening to closing. Quran wording is canonical Arabic with Pickthall English. Non-Quran meanings are original concise renderings of the cited ancient Arabic, with approximate Roman reading aids where provided. This is a meaning lab, not a complete legal prayer manual. The licensed local Al-Fatiha recording plays the full surah; audio for the other recitations is not included.'))
app=ROOT/'apps/understand-salah-lab';(app/'public/audio').mkdir(exist_ok=True)
shutil.copyfile(B/'fatiha.mp3',app/'public/audio/fatiha.mp3')
(app/'public/audio/ATTRIBUTION.txt').write_text('Al-Fatiha recording\nCreator: Adeel Shaikh\nSource: https://commons.wikimedia.org/wiki/File:Surah-Fathia.flac\nOriginal creator upload identifies this as own work.\nLicense: Creative Commons Attribution-ShareAlike 4.0 International\nhttps://creativecommons.org/licenses/by-sa/4.0/\nBundled file is Wikimedia Commons MP3 transcode. Audio content unchanged.\nOriginal date: 7 November 2011.\nOriginal file: https://upload.wikimedia.org/wikipedia/commons/e/ea/Surah-Fathia.flac\nMP3: https://upload.wikimedia.org/wikipedia/commons/transcoded/e/ea/Surah-Fathia.flac/Surah-Fathia.flac.mp3\nNo endorsement implied. This media retains its CC BY-SA license independently of MIT application code.\n',encoding='utf-8')
p=app/'src/data/sources.json';sources=json.loads(p.read_text(encoding='utf-8'));sources.extend([dict(label='Al-Fatiha audio · Adeel Shaikh',url=audio['source'],kind='Audio',note=audio['note']),dict(label='Creative Commons Attribution-ShareAlike 4.0',url=audio['licenseUrl'],kind='Media license',note='The bundled recording remains under this license.')]);p.write_text(json.dumps(sources,ensure_ascii=False,indent=2),encoding='utf-8')
p=app/'src/data/provenance.json';pr=json.loads(p.read_text(encoding='utf-8'));pr['audioSha256']=hashlib.sha256((app/'public/audio/fatiha.mp3').read_bytes()).hexdigest();p.write_text(json.dumps(pr,indent=2),encoding='utf-8')
(B/'hadith-excerpts.json').write_text(json.dumps([dict(id=l['id'],arabic=l['arabic'],sources=l['sources']) for l in lessons if not l['passage']],ensure_ascii=False,indent=2),encoding='utf-8')
